function validate([zero, one, limit]) {
  for (const [name, value] of [['zero', zero], ['one', one], ['limit', limit]]) {
    if (!Number.isInteger(value) || value < 1 || value > 200) return `${name} must be a whole number from 1 to 200.`;
  }
  return null;
}

