function numberOfStableArrays(zero, one, limit) {
  const MOD = 1_000_000_007;
  const endZero = Array.from({ length: zero + 1 }, () => new Array(one + 1).fill(0));
  const endOne = Array.from({ length: zero + 1 }, () => new Array(one + 1).fill(0));
  for (let i = 1; i <= Math.min(zero, limit); i++) {
    endZero[i][0] = 1;
  }
  for (let j = 1; j <= Math.min(one, limit); j++) {
    endOne[0][j] = 1;
  }
  for (let i = 1; i <= zero; i++) {
    for (let j = 1; j <= one; j++) {
      let zeros = endZero[i - 1][j] + endOne[i - 1][j];
      if (i > limit) {
        zeros -= endOne[i - limit - 1][j];
      }
      let ones = endZero[i][j - 1] + endOne[i][j - 1];
      if (j > limit) {
        ones -= endZero[i][j - limit - 1];
      }
      endZero[i][j] = (zeros % MOD + MOD) % MOD;
      endOne[i][j] = (ones % MOD + MOD) % MOD;
    }
  }
  return (endZero[zero][one] + endOne[zero][one]) % MOD;
}

