function numberOfStableArrays(zero, one, limit) {
  // A stable array is a sequence of alternating runs, each 1..limit long. ways[i][j][v] counts arrays with
  // i zeros and j ones whose last run has value v, by trying every length t of that last run.
  const MOD = 1000000007;
  const ways = [];
  for (let i = 0; i <= zero; i++) {
    ways.push([]);
    for (let j = 0; j <= one; j++) {
      const cell = [0, 0];
      for (let t = 1; t <= Math.min(i, limit); t++) {
        cell[0] = (cell[0] + (i - t === 0 && j === 0 ? 1 : ways[i - t][j][1])) % MOD;
      }
      for (let t = 1; t <= Math.min(j, limit); t++) {
        cell[1] = (cell[1] + (i === 0 && j - t === 0 ? 1 : ways[i][j - t][0])) % MOD;
      }
      ways[i].push(cell);
    }
  }
  return (ways[zero][one][0] + ways[zero][one][1]) % MOD;
}

